"""pdfrender credentials. Generated by listing-sync (infra scripts/listing_sync/connectors/dify.py); edits are overwritten."""

from typing import Any

import httpx
from dify_plugin import ToolProvider
from dify_plugin.errors.tool import ToolProviderCredentialValidationError

from tools._client import api_key, get


class PdfrenderProvider(ToolProvider):
    def _validate_credentials(self, credentials: dict[str, Any]) -> None:
        if not api_key(credentials):
            return  # no key: the tools use the free daily allowance
        try:
            response = get(credentials, '/v1/me')
        except httpx.HTTPError as err:
            msg = f"The pdfrender API is unreachable: {err}"
            raise ToolProviderCredentialValidationError(msg) from err
        if response.status_code in (401, 403):
            msg = "The pdfrender API rejected this API key."
            raise ToolProviderCredentialValidationError(msg)
        if response.status_code != 200:
            msg = f"The pdfrender API answered {response.status_code}."
            raise ToolProviderCredentialValidationError(msg)
        # An unknown key is no error to the API: it answers as without a key.
        if not response.json().get("is_keyed"):
            msg = (
                "The pdfrender API does not know this API key. Check it, or "
                "leave the field empty to use the free daily allowance."
            )
            raise ToolProviderCredentialValidationError(msg)
